create or replace function public.ils_professional_security_approval_execution_bind(p_queue_id uuid,p_approval_log_id uuid,p_approved_action text,p_execution_nonce text,p_ttl_minutes integer default 15) returns uuid language plpgsql security definer set search_path=public as $$ declare q record; a record; r record; b_id uuid; snap text; begin if p_queue_id is null or p_approval_log_id is null or nullif(trim(p_approved_action),'') is null or nullif(trim(p_execution_nonce),'') is null then raise exception 'EXECUTION_BINDING_INVALID_INPUT'; end if; if p_ttl_minutes < 1 or p_ttl_minutes > 60 then raise exception 'EXECUTION_BINDING_INVALID_TTL'; end if; select * into q from public.ils_professional_security_review_queue where id=p_queue_id for update; if not found or q.review_status <> 'APPROVED' then raise exception 'EXECUTION_BINDING_APPROVAL_NOT_READY'; end if; select * into a from public.ils_professional_security_review_approval_log where id=p_approval_log_id and queue_id=p_queue_id for update; if not found or a.approval_decision <> 'APPROVE' or a.approved_action <> p_approved_action then raise exception 'EXECUTION_BINDING_ACTION_MISMATCH'; end if; select * into r from public.ils_professional_assignment_mutation_alert_escalation_rules where decision=q.decision and action_code=p_approved_action and active=true; if not found or r.destructive_action_allowed=true then raise exception 'EXECUTION_BINDING_ACTION_NOT_ALLOWED'; end if; if exists(select 1 from public.ils_professional_security_approval_execution_bindings where queue_id=p_queue_id) then raise exception 'EXECUTION_BINDING_ALREADY_EXISTS'; end if; if exists(select 1 from public.ils_professional_security_approval_execution_bindings where execution_nonce=p_execution_nonce) then raise exception 'EXECUTION_BINDING_NONCE_REPLAY'; end if; snap:=encode(digest(concat_ws('|',q.id::text,q.review_status,q.decision,q.source_failure_code,a.id::text,a.approval_decision,a.approved_action,coalesce(a.approval_reason,'')),'sha256'),'hex'); insert into public.ils_professional_security_approval_execution_bindings(queue_id,approval_log_id,approved_action,execution_status,bound_at,expires_at,execution_nonce,approval_snapshot_hash) values(q.id,a.id,p_approved_action,'READY',now(),now()+(p_ttl_minutes||' minutes')::interval,p_execution_nonce,snap) returning id into b_id; return b_id; end; $$; revoke all on function public.ils_professional_security_approval_execution_bind(uuid,uuid,text,text,integer) from public,anon,authenticated; grant execute on function public.ils_professional_security_approval_execution_bind(uuid,uuid,text,text,integer) to service_role; create or replace function public.ils_professional_security_approval_execution_consume(p_binding_id uuid,p_execution_nonce text,p_expected_action text,p_approval_snapshot_hash text) returns boolean language plpgsql security definer set search_path=public as $$ declare b record; q record; a record; snap text; did_execute boolean := false; begin if p_binding_id is null or nullif(trim(p_execution_nonce),'') is null or nullif(trim(p_expected_action),'') is null or nullif(trim(p_approval_snapshot_hash),'') is null then raise exception 'EXECUTION_CONSUME_INVALID_INPUT'; end if; select * into b from public.ils_professional_security_approval_execution_bindings where id=p_binding_id for update; if not found then raise exception 'EXECUTION_CONSUME_BINDING_NOT_FOUND'; end if; if b.execution_status <> 'READY' then raise exception 'EXECUTION_CONSUME_NOT_READY'; end if; if b.execution_nonce <> p_execution_nonce then raise exception 'EXECUTION_CONSUME_NONCE_MISMATCH'; end if; if b.approved_action <> p_expected_action then raise exception 'EXECUTION_CONSUME_ACTION_MISMATCH'; end if; if b.expires_at is null or now() > b.expires_at then update public.ils_professional_security_approval_execution_bindings set execution_status='BLOCKED' where id=b.id; raise exception 'EXECUTION_CONSUME_EXPIRED'; end if; select * into q from public.ils_professional_security_review_queue where id=b.queue_id for update; select * into a from public.ils_professional_security_review_approval_log where id=b.approval_log_id for update; if not found or q.review_status <> 'APPROVED' or a.approval_decision <> 'APPROVE' or a.approved_action <> b.approved_action then raise exception 'EXECUTION_CONSUME_APPROVAL_DRIFT'; end if; snap:=encode(digest(concat_ws('|',q.id::text,q.review_status,q.decision,q.source_failure_code,a.id::text,a.approval_decision,a.approved_action,coalesce(a.approval_reason,'')),'sha256'),'hex'); if snap <> b.approval_snapshot_hash or snap <> p_approval_snapshot_hash then raise exception 'EXECUTION_CONSUME_SNAPSHOT_MISMATCH'; end if; update public.ils_professional_security_approval_execution_bindings set execution_status='EXECUTED',executed_at=now() where id=b.id and execution_status='READY' returning true into did_execute; if not did_execute then raise exception 'EXECUTION_CONSUME_REPLAY'; end if; return true; end; $$; revoke all on function public.ils_professional_security_approval_execution_consume(uuid,text,text,text) from public,anon,authenticated; grant execute on function public.ils_professional_security_approval_execution_consume(uuid,text,text,text) to service_role; alter table public.ils_professional_security_approval_execution_bindings alter column expires_at set default (now()+interval '15 minutes');